sources=json.loads((PACK/'source.json').read_text());answer=json.loads((PACK/'answer.json').read_text());context=json.loads((PACK/'context.json').read_text());snapshot=json.loads((PACK/'reference-targets.json').read_text());schema=json.loads(json.dumps(answer));validate_answer(schema,sources)
checks=[];deltas=[]
