for x in sources+context:
 key=x['code_id'],x['source_id'];current=db.execute('SELECT source_sha256,content_xml FROM articles WHERE code_id=? AND id=?',key).fetchone();assert current==(x['source_sha256'],x['source_xml']);assert source_notes(db,*key)==x['source_notes_xml'];old=x.get('previous_draft');d=db.execute('SELECT proposed_xml FROM drafts WHERE code_id=? AND source_id=?',key).fetchone();expected=old['proposed_xml']if old else x.get('proposed_xml');assert (d[0]if d else None)==expected,x['number'];checks.append(dict(number=x['number'],source_sha256=x['source_sha256'],source_body_sha256=sha(x['source_xml']),source_notes_sha256=sha(x['source_notes_xml']),beforeimage_sha256=sha(expected)))
for row,source in zip(answer,sources):
 old=re.findall('<p>.*?</p>',source['previous_draft']['proposed_xml'],re.S);new=re.findall('<p>.*?</p>',row['proposed_xml'],re.S);assert len(old)==len(new);changed=[i for i,(a,b)in enumerate(zip(old,new))if a!=b];assert changed==[next(i for i,p in enumerate(old)if p.startswith('<p>La durée hebdomadaire')),len(old)-1],(row['number'],changed)
 assert 'L. 3123-27'not in row['proposed_xml'];assert 'aucune durée globale minimale' in row['proposed_xml'];assert 'ne réduit ni la durée contractuelle garantie ni la rémunération correspondante'in row['proposed_xml'];assert row['substantive_impact']['classification']=='mixed';assert {e['kind']for e in row['substantive_impact']['effects']}=={'relief_extended','complexity_added'}
 deltas.append(dict(number=row['number'],changed_paragraphs_zero_based=changed,other_previous_draft_paragraphs_exact=True,proposed_sha256=sha(row['proposed_xml']),classification='mixed',specific_favourable_exception_preserved=('sauf lorsque le contrat le prévoit pour tenir compte des difficultés particulièrement importantes du salarié'in row['proposed_xml'])if row['number']=='L5132-15-1'else'not_applicable'))
db.rollback();db.close()
report=dict(version=1,reviewed_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),reviewer='rewrite_travail',independent_from_this_pack_author=True,semantic_review_by_jurist=False,scope='Three whole official sources, notes, full prior drafts and proposed articles; six complete context articles and six complete reference targets.',verdict='no_blocking_defect_in_bounded_review',blocking_findings=[],source_and_beforeimage_guards_current=True,reference_coherence_guards_current=True,validation_passed=True,file_sha256={n:sha((PACK/n).read_bytes())for n in ['source.json','answer.json','context.json','reference-targets.json']},checks=checks,deltas=deltas,findings=[
 dict(subject='Cumul',conclusion='La condition source de durée globale au moins égale au temps plein ou au plancher général est retirée dans chacun des trois articles ; la dispense est autonome et ne renvoie plus au L3123-27 désormais sans seuil. Aucune nouvelle autorisation ou attestation particulière. Le minimum spécial de vingt heures hors dispense demeure.'),
 dict(subject='Transitions et contrat',conclusion='La dispense favorable couvre expressément les anciens contrats en cours et les nouveaux ; elle ne permet aucune réduction unilatérale du volume garanti ou du salaire. Anciens termes et créances, conversion sans nouvel essai, suspensions et départ sans préavis vers un autre emploi sont conservés. La fin de parcours ou d’aide ne rompt pas l’emploi. Le renvoi L1241-1 conserve les droits anciens et n’autorise pas de nouveau CDD.'),
 dict(subject='Avantages',conclusion='Les exceptions pour aménagement de peine, poursuite de formation, salariés de cinquante ans et plus et handicap restent présentes. Les associations intermédiaires et chantiers gardent les décisions d’au plus un an jusqu’à soixante mois pour difficultés particulièrement importantes ; l’exception contractuelle propre aux chantiers au minimum de vingt heures reste entière. Les validations de trimestres renvoient toujours à L351-2 ; aucune aide illimitée n’est créée.'),
 dict(subject='Coût de complexité',conclusion='Mixed est justifié : les quatre et vingt-quatre mois passent du CDD au calendrier autonome du parcours, à gérer à côté de l’emploi sans terme ; ce coût supplémentaire provient du précédent projet et reste réellement présent face à la source. La clé insertion-parcours-distinct-emploi est commune aux trois articles ; ne pas sommer trois calendriers comme trois créations. Le contrat unique et son effet sur l’ancienne durée minimale d’emploi relèvent de la mesure commune déjà analysée, pas d’une économie additionnelle prouvée.'),
 dict(subject='Six cibles',conclusion='Les cibles L1221-2, L1234-1, L1234-9, L1241-1, L1242-3 et L1243-2 sont cohérentes avec le changement limité : absence de nouveau CDD, préavis ordinaire distinct de la dispense spécifique de départ, barème patronal non assimilé aux droits salariaux ou réparations. Les six contextes L3123-7/19/27 et L5132-6/11/15 ont aussi été lus. La correction ne transpose pas les garanties mensuelles particulières de l’intérim à toutes les associations ni ne retire l’égalité de rémunération de L5132-11.'),
 dict(subject='Limite de portée',conclusion='Cette passe ne certifie pas tous les décrets d’insertion, crédits d’aide, conventions ou règles de calcul de retraite. La phrase maintenant le cadre des aides ne démontre pas à elle seule leur financement. Aucun chiffrage d’économie nationale ni réduction nette globale ; les références et avant-images doivent encore rester identiques sous verrou avant inscription.')])
